import type { Config } from "drizzle-kit";

/**
 * Generated migrations land in ./drizzle and are committed after review.
 *
 * Grants, functions and table partitioning are not generated by drizzle-kit. Those live in
 * hand-authored migrations created with `pnpm db:custom`, in the same numbered sequence
 * (ADR-0001) — today that is all of `0001_grants_functions_and_partitions.sql`.
 *
 * `0000_baseline.sql` is generated output with two hand edits, named in its own header,
 * that a regeneration would lose. Read it before regenerating anything.
 */
export default {
  dialect: "postgresql",
  schema: "./src/schema/index.ts",
  out: "./drizzle",
  casing: "snake_case",
  dbCredentials: {
    url: process.env["DATABASE_URL"] ?? "postgres://idenzy:idenzy@localhost:5432/idenzy",
  },
  verbose: true,
  strict: true,
} satisfies Config;
